import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import ProtectedRoute from './ProtectedRoute';
import Login from '../../components/Authentication/Login';
import DashBoard from '../../components/Dashboard/dashboard';
import Profile from '../../components/Profile/index';
import StaffProfile from '../../components/StaffProfile/index';
import HomeworkPage from '../../components/Homework/HomeworkPage';
import { USER_PORTAL_PERMISSIONS } from '../../services/commonUtills/FormValidations';

export const AppRouters = () => {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<Login />} />
        <Route
          path="/dashboard"
          element={
            <ProtectedRoute>
              <DashBoard />
            </ProtectedRoute>
          }
        />
        <Route
          path="/profile"
          element={
            <ProtectedRoute
              permissionCodes={USER_PORTAL_PERMISSIONS.PROFILE}
              userTypes={['STUDENT']}
            >
              <Profile />
            </ProtectedRoute>
          }
        />
        <Route
          path="/staff-profile"
          element={
            <ProtectedRoute
              permissionCodes={USER_PORTAL_PERMISSIONS.PROFILE}
              userTypes={['STAFF']}
            >
              <StaffProfile />
            </ProtectedRoute>
          }
        />
        <Route
          path="/homework"
          element={
            <ProtectedRoute
              permissionCodes={USER_PORTAL_PERMISSIONS.HOMEWORK}
              userTypes={['STUDENT', 'STAFF']}
            >
              <HomeworkPage />
            </ProtectedRoute>
          }
        />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
};
